pub struct Histogram {
    data: Vec<u64>,
}

impl Histogram {
    fn new(bins: u32) -> Option<Self> {
        if bins == 0 {
            return None;
        }
        Some(Self {
            data: vec![0u64; bins as usize],
        })
    }
}

#[no_mangle]
pub extern "C" fn histogram_new(bins: u32) -> *mut Histogram {
    Histogram::new(bins)
        .map(|h| Box::into_raw(Box::new(h)))
        .unwrap_or_else(|| std::ptr::null_mut())
}

#[no_mangle]
pub unsafe extern "C" fn histogram_add(h: *mut Histogram, bin: u32) -> i32 {
    if h.is_null() {
        return -1;
    }
    if bin as usize >= (*h).data.len() {
        return -2;
    }
    (*h).data[bin as usize] += 1;
    0
}

#[no_mangle]
pub unsafe extern "C" fn histogram_count(h: *const Histogram, bin: u32) -> u64 {
    if h.is_null() {
        return 0;
    }
    if bin as usize < (*h).data.len() {
        (*h).data[bin as usize]
    } else {
        0
    }
}

#[no_mangle]
pub unsafe extern "C" fn histogram_free(h: *mut Histogram) {
    if !h.is_null() {
        let _ = Box::from_raw(h);
    }
}
```

